class Solution(object):
    def countTime(self, time):
        """
        :type time: str
        :rtype: int
        """
        h, m = time.split(':')

        # Count possible hours
        if h[0] == '?' and h[1] == '?':
            hours = 24
        elif h[0] == '?':
            hours = 3 if int(h[1]) < 4 else 2
        elif h[1] == '?':
            hours = 10 if h[0] == '0' or h[0] == '1' else 4
        else:
            hours = 1

        # Count possible minutes
        if m[0] == '?' and m[1] == '?':
            minutes = 60
        elif m[0] == '?':
            minutes = 6
        elif m[1] == '?':
            minutes = 10
        else:
            minutes = 1

        return hours * minutes
